const res = $input.item.json;
const valueRanges = res.valueRanges || [];

// 1. Fecha de hoy local en formato YYYY-MM-DD
const ahora = new Date();
const anio = ahora.getFullYear();
const mes = String(ahora.getMonth() + 1).padStart(2, '0');
const dia = String(ahora.getDate()).padStart(2, '0');
const fechaHoy = `${anio}-${mes}-${dia}`;

// 2. Limpieza y parseo de numeros con coma o punto
function parseNum(val, defaultVal = undefined) {
  if (val === undefined || val === null || val === '') return defaultVal;
  const clean = String(val).replace(',', '.').trim();
  const num = Number(clean);
  return isNaN(num) ? defaultVal : num;
}

function sheetToObjects(values) {
  if (!values || values.length < 2) return [];
  const headers = values[0].map(h => (h || '').toString().trim());
  return values.slice(1).map(row => {
    const obj = {};
    headers.forEach((h, idx) => {
      obj[h] = row[idx] !== undefined ? String(row[idx]).trim() : '';
    });
    return obj;
  });
}

// 3. Extraer los rangos devueltos por batchGet
const cfgValues = valueRanges.find(r => r.range && r.range.includes('hotel_config'))?.values || [];
const reglasValues = valueRanges.find(r => r.range && r.range.includes('reglas_umbrales'))?.values || [];
const factoresValues = valueRanges.find(r => r.range && r.range.includes('factores_segmentacion'))?.values || [];
const schemaValues = valueRanges.find(r => r.range && r.range.includes('modelo_schema'))?.values || [];

const cfgRows = sheetToObjects(cfgValues);
const filasReglas = sheetToObjects(reglasValues);
const filasFactores = sheetToObjects(factoresValues);
const filasSchema = sheetToObjects(schemaValues);

if (filasSchema.length === 0) {
  throw new Error("[VALIDACION CRITICA]: No se encontro o esta vacia la pestana 'modelo_schema' en Google Sheets.");
}

// 4. Parsear hotel_config
const cfg = {};
cfgRows.forEach(r => {
  if (r.parametro) cfg[r.parametro] = r.valor;
});

// 5. Parsear reglas y factores soportando decimales con coma
const tablas_pricing = {
  reglas_ocupacion: [],
  factor_ocupacion: [],
  reglas_pace: [],
  factor_pace: [],
  reglas_revpar: [],
  reglas_pickup: [],
  reglas_riesgo: [],
  factores_canal: {},
  factores_tipo: {},
  factores_pais: {}
};

filasReglas.forEach(r => {
  const min = parseNum(r.min);
  const max = parseNum(r.max);
  const factor = parseNum(r.factor);
  const item = {
    min,
    max,
    estado: r.estado || undefined,
    clasificacion: r.estado || undefined,
    riesgo: r.riesgo || undefined,
    factor
  };

  if (r.tipo_regla === 'ocupacion') {
    tablas_pricing.reglas_ocupacion.push(item);
    if (factor !== undefined) tablas_pricing.factor_ocupacion.push({ min, max, factor });
  } else if (r.tipo_regla === 'pace') {
    tablas_pricing.reglas_pace.push(item);
    if (factor !== undefined) tablas_pricing.factor_pace.push({ min, max, factor });
  } else if (r.tipo_regla === 'revpar') {
    tablas_pricing.reglas_revpar.push(item);
  } else if (r.tipo_regla === 'pickup') {
    tablas_pricing.reglas_pickup.push(item);
  } else if (r.tipo_regla === 'riesgo_ocupacion') {
    tablas_pricing.reglas_riesgo.push(item);
  }
});

filasFactores.forEach(f => {
  const val = parseNum(f.factor, 1.0);
  const dim = f.dimension;
  const clave = f.clave;
  if (dim === 'canal') tablas_pricing.factores_canal[clave] = val;
  else if (dim === 'tipo') tablas_pricing.factores_tipo[clave] = val;
  else if (dim === 'pais') tablas_pricing.factores_pais[clave] = val;
});

let startData = {};
try { startData = $('Start').first()?.json || {}; } catch (e) {}

const diasVista = parseInt(cfg.dias_vista_default) || 14;

const hotelConfig = {
  hotel_id: startData.hotel_id || cfg.hotel_id,
  nombre: cfg.nombre,
  capacidad_total: parseNum(cfg.capacidad_total),
  dias_vista_default: diasVista,
  prefijo_archivo: cfg.prefijo_archivo,
  rating_referencia: parseNum(cfg.rating_referencia, 4.5),
  modelo_endpoint: cfg.modelo_endpoint,
  ubicacion: {
    lat: parseNum(cfg.lat),
    lon: parseNum(cfg.lon),
    ciudad: cfg.ciudad,
    comunidad_autonoma: cfg.comunidad_autonoma,
    codigo_pais: cfg.codigo_pais
  },
  reglas_pricing: {
    suelo_ajuste: parseNum(cfg.suelo_ajuste, 0.75),
    techo_ajuste: parseNum(cfg.techo_ajuste, 1.35),
    bonus_festivo: parseNum(cfg.bonus_festivo, 1.10),
    bonus_vacaciones: parseNum(cfg.bonus_vacaciones, 1.05)
  },
  tablas_pricing,
  modelo_schema: filasSchema
};

return [{
  json: {
    hotelConfig,
    periodo: String(hotelConfig.dias_vista_default),
    fecha_inicio: fechaHoy
  }
}];
